<?php
require __DIR__.'/includes/bootstrap.php';require_permission('reports.view');ensure_runtime_schema();$pdo=db();$from=(string)($_GET['from']??date('Y-m-d',strtotime('-30 days')));$to=(string)($_GET['to']??date('Y-m-d'));if(!strtotime($from))$from=date('Y-m-d',strtotime('-30 days'));if(!strtotime($to))$to=date('Y-m-d');$q=$pdo->prepare('SELECT activity_date day,customers_registered customers,drivers_registered drivers FROM daily_growth_counts WHERE activity_date BETWEEN ? AND ? ORDER BY activity_date DESC');$q->execute([$from,$to]);$registrations=$q->fetchAll();$q=$pdo->prepare('SELECT e.full_name,COUNT(t.id) assigned,SUM(t.status="completed") completed,SUM(t.status NOT IN ("completed","cancelled") AND t.due_at<UTC_TIMESTAMP()) overdue FROM employees e LEFT JOIN tasks t ON t.primary_assignee_id=e.id AND DATE(t.created_at) BETWEEN ? AND ? GROUP BY e.id,e.full_name ORDER BY assigned DESC');$q->execute([$from,$to]);$productivity=$q->fetchAll();$title='Reports & Analytics';$active='reports';include __DIR__.'/includes/header.php';?>
<section class="section-toolbar reveal"><div><p class="eyebrow">Management intelligence</p><h2>Reports & analytics</h2><p class="muted">Count-only customer/driver growth and employee execution for the selected period.</p></div><?php if(can('reports.export')):?><a class="btn btn-soft" href="<?=e(url('handlers/export-report.php?'.http_build_query(['from'=>$from,'to'=>$to])))?>"><i data-lucide="download"></i>Export report</a><?php endif;?></section><section class="panel reveal stagger-1"><form class="filter-bar" method="get" action="<?=e(url('reports.php'))?>"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn btn-primary">Apply range</button><button class="btn btn-soft" type="button" onclick="window.print()"><i data-lucide="printer"></i>Print</button></form></section><section class="report-grid reveal stagger-2"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Registration growth</p><h3>Daily counts</h3></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customers</th><th>Drivers</th><th>Combined</th></tr></thead><tbody><?php if(!$registrations):?><tr><td colspan="4">No registration counts in this range.</td></tr><?php else:foreach($registrations as $r):?><tr><td><?=e(date('d M Y',strtotime($r['day'])))?></td><td><?=number_format((int)$r['customers'])?></td><td><?=number_format((int)$r['drivers'])?></td><td><?=number_format((int)$r['customers']+(int)$r['drivers'])?></td></tr><?php endforeach;endif;?></tbody></table></div></article><article class="panel"><div class="panel-heading"><div><p class="eyebrow">Workload</p><h3>Employee task activity</h3></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Assigned</th><th>Completed</th><th>Overdue</th></tr></thead><tbody><?php foreach($productivity as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=number_format((int)$r['assigned'])?></td><td><?=number_format((int)$r['completed'])?></td><td class="<?=$r['overdue']?'danger-text':''?>"><?=number_format((int)$r['overdue'])?></td></tr><?php endforeach;?></tbody></table></div></article></section>
<?php include __DIR__.'/includes/footer.php';?>
